"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8670],{83959:e=>{e.exports=JSON.parse('{"functions":[{"name":"startVoting","desc":"Opens a vote over `payload.pool` for `payload.voters`, zeroing the tallies and\\ntelling those clients to show the vote UI.\\n\\nNo-ops if either the pool or the voter list is missing. If a vote is somehow\\nalready running it is stopped first, so state never bleeds between rounds.","params":[{"name":"payload","desc":"","lua_type":"{ pool: { MinigameTypes.VotePoolItem }?, voters: { Player }? }"}],"returns":[],"function_type":"static","source":{"line":103,"path":"src/Server/Features/Minigames/VoteService.luau"}},{"name":"startPlayerVote","desc":"Adds a player to an already-running vote and sends them the current pool. Used\\nfor players who load in mid-vote.\\n\\nReturns `false` if they are already eligible or have already voted. Note this\\ngrows `voters`, which raises the bar for the \\"everyone has voted\\" early exit \u2014\\ndeliberately, so a late joiner is not disenfranchised by the vote closing the\\ninstant they appear.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"Whether they were added","lua_type":"boolean"}],"function_type":"static","source":{"line":147,"path":"src/Server/Features/Minigames/VoteService.luau"}},{"name":"results","desc":"Returns the current tallies as `{ [gameModeName]: voteCount }`. Broadcast to\\nclients after every ballot so the vote cards update live.","params":[],"returns":[{"desc":"","lua_type":"{ [string]: number }"}],"function_type":"static","source":{"line":171,"path":"src/Server/Features/Minigames/VoteService.luau"}},{"name":"stop","desc":"Closes the vote: clears the voting flag, fires `VoteEnded`, and tells all\\nclients to dismiss the vote UI.\\n\\nGuarded by the voting flag, so the redundant calls from both the timeout path\\nand the all-voted path cannot double-fire `VoteEnded`.\\n\\nDoes **not** clear the pool or tallies \u2014 [VoteService.getWinner] does that, so\\nthe results survive long enough to be read.","params":[],"returns":[],"function_type":"static","source":{"line":188,"path":"src/Server/Features/Minigames/VoteService.luau"}},{"name":"isPlayerVoting","desc":"Whether a player is eligible to vote in the current round. Eligibility, not\\nparticipation \u2014 see [VoteService.hasVoted].","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":212,"path":"src/Server/Features/Minigames/VoteService.luau"}},{"name":"hasVoted","desc":"Whether a player has already cast a ballot this round.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":225,"path":"src/Server/Features/Minigames/VoteService.luau"}},{"name":"cast","desc":"Records a player\'s vote for a game mode.\\n\\n:::info Gated by [FeatureFlags].VoteChange\\nWhen that flag is off \u2014 the default \u2014 a player who has already voted is\\nsilently ignored, making the first ballot final. With it on, the previous vote\\nis decremented and the new one incremented, so players may switch freely until\\nthe vote closes.\\n:::\\n\\nIgnores votes when no vote is running, the payload is empty, or the player is\\nnot eligible. Players holding the `double_votes` gamepass move the tally by 2\\nrather than 1, applied to both the decrement and the increment so a changed\\nweighted vote stays balanced.\\n\\nBroadcasts the updated tallies to everyone, then closes the vote if every\\neligible player has now voted.","params":[{"name":"player","desc":"The voter","lua_type":"Player"},{"name":"payload","desc":"Name of the game mode being voted for","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":253,"path":"src/Server/Features/Minigames/VoteService.luau"}},{"name":"getWinner","desc":"Returns the winning candidate and resets the vote state.\\n\\nSeeded with a random pool entry so a round where nobody voted still produces a\\nplayable game, then replaced by whichever mode has the strictly highest tally.\\nStrict comparison means a tie is resolved in favour of whichever mode iteration\\nreached first \u2014 effectively arbitrary, which is acceptable for a tie.\\n\\nClears `voters`, `pool` and `votes` on the way out, so this may only be called\\nonce per vote.","params":[],"returns":[{"desc":"","lua_type":"MinigameTypes.VotePoolItem"}],"function_type":"static","source":{"line":315,"path":"src/Server/Features/Minigames/VoteService.luau"}}],"properties":[],"types":[],"name":"VoteService","desc":"Runs the pre-round vote that picks the next minigame. Driven by\\n[GameService.voteWrap], which supplies the candidate pool and waits on\\n`VoteEnded`.\\n\\n### State\\n\\nOne vote at a time, held in module-level state rather than on an instance:\\n\\n- `pool` \u2014 the [VotePoolItem] candidates being voted on\\n- `votes` \u2014 game mode name to vote tally\\n- `voters` \u2014 who is eligible to vote\\n- `playerEntries` \u2014 who has voted, and for what\\n\\nStarting a new vote while one is running stops the old one first, so the state\\nis never mixed between rounds. [VoteService.getWinner] resets `pool` and\\n`votes` as a side effect of reading them.\\n\\n### Ending a vote\\n\\nTwo ways: everyone eligible has voted (checked after every ballot), or\\n[GameService] times it out. Either path goes through [VoteService.stop], which\\nfires `VoteEnded` exactly once and tells clients to close the UI.\\n\\n### Weighted votes\\n\\nA player holding the `double_votes` gamepass casts two votes instead of one.\\nThe weight is applied symmetrically on add and subtract, so changing a\\nweighted vote leaves the tallies consistent.\\n\\n### Vote changing\\n\\nWhether a player may change their vote is itself flagged \u2014 see\\n[VoteService.cast].\\n\\nGated by [FeatureFlags].Minigames \u2014 disabled by default; per-project forks\\nenable it deliberately. This module has no `init`; it is inert unless\\n[GameService] drives it, which only happens with the flag on.","tags":["dormant"],"realm":["Server"],"source":{"line":47,"path":"src/Server/Features/Minigames/VoteService.luau"}}')}}]);